import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"井","description":"焦氏易林注 - 井","frontmatter":{"title":"井","description":"焦氏易林注 - 井"},"headers":[],"relativePath":"classics/jiaoyilin/048.md","filePath":"classics/jiaoyilin/048.md"}'),l={name:"classics/jiaoyilin/048.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h3 id="井-1" tabindex="-1">井 <a class="header-anchor" href="#井-1" aria-label="Permalink to “井”">​</a></h3><h3 id="井之乾" tabindex="-1">井之乾 <a class="header-anchor" href="#井之乾" aria-label="Permalink to “井之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>左輔右弼，金玉滿堂。常盈不亡，富如厫倉。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《坤》。○厫，宋元本作敖，依汲古。</p><h3 id="井之坤" tabindex="-1">井之坤 <a class="header-anchor" href="#井之坤" aria-label="Permalink to “井之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>雨師娶婦，黃巖季女。成禮既婚，相呼南去。膏澤田裡，年歲大喜。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《晉》。南去，宋本作而歸，汲古作南上，依元本。田裡，汲古作下土，依宋元本。又末句宋元本無，依汲古。</p><h3 id="井之屯" tabindex="-1">井之屯 <a class="header-anchor" href="#井之屯" aria-label="Permalink to “井之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>螟蟲為賊，害我嘉穀。盡禾殫麥，家無所得。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《革》。○嘉穀，宋元本作稼穡，家作秋，均依汲古。得，汲古作食。第三句汲古作中留空虛，均依宋元本。</p><h3 id="井之蒙" tabindex="-1">井之蒙 <a class="header-anchor" href="#井之蒙" aria-label="Permalink to “井之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>跛躃難步，遲不及舍。露宿澤陂，亡其襦褲。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為步，坎蹇，故曰跛躃難步。艮為舍，艮止，故不及舍。坎為露、為宿、為澤陂，震為襦褲，坤為亡，故又曰亡其襦褲。</p><h3 id="井之需" tabindex="-1">井之需 <a class="header-anchor" href="#井之需" aria-label="Permalink to “井之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>大夫祈父，無地不涉。為吾相土，莫如韓樂。可以居止，長安富有。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為父，兌言，故曰祈父。陳樸園雲：《詩》：&quot;祈父予王之爪牙&quot;，《毛傳》：&quot;祈父司馬&quot;也。蹶父為司馬之官，《尚書》稱司馬，亦曰祈父。圻祈古通用。《詩大雅韓奕篇》：&quot;蹶父孔武，靡國不到；為韓姞相攸，莫如韓樂&quot;，林所本也。伏坤為土地，艮為居止、為安。乾為富，兌悅，故曰樂。○祈，各本多作行，依汲古。</p><h3 id="井之訟" tabindex="-1">井之訟 <a class="header-anchor" href="#井之訟" aria-label="Permalink to “井之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>少孤無父，長失慈母。悖悖煢煢，莫與為耦。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坎為孤，震為父，坤喪，故無父。震為長，坤為慈母，坤亡，故失慈母。坤寡，故曰煢煢，故無耦也。</p><h3 id="井之師" tabindex="-1">井之師 <a class="header-anchor" href="#井之師" aria-label="Permalink to “井之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>側弁醉客，長舌作兇。披髪夜行，迷亂相誤，亡失居處。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>艮為冠，二四艮覆，故曰側弁。《詩小雅》：&quot;側弁之俄，屢舞傞傞&quot;。震為客，坤迷，故曰醉客。兌為舌，二至上兌形特長，故曰長舌。震為髪，坤為夜、為迷亂、為亡失。○處，宋元本作止，依汲古。</p><h3 id="井之比" tabindex="-1">井之比 <a class="header-anchor" href="#井之比" aria-label="Permalink to “井之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>馬驚車破，王墜深津。身死魂去，離其室廬。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>震為車馬，坎為破，三至五震覆，故馬驚車破。九五為王，坎陷，一陽陷坤水中，故曰王墜深津。坤為死、為身，乾為魂，坤為白色，乾伏，故曰魂去。艮為室。○車破，宋元本作破處，依汲古。第二句依汲古，宋元本作王孫沈溝。死，各本作絕，依局本。第四句宋元本作自為患害，依汲古。汲古末多貞難無虞四字，依宋元本刪。</p><h3 id="井之小畜" tabindex="-1">井之小畜 <a class="header-anchor" href="#井之小畜" aria-label="Permalink to “井之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>東行述職，徵討不服。侵齊伐陳，銜璧為臣，大得意還。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。震為東、為徵討、為陳、為璧，兌為口，故曰銜璧。巽為齊，艮為臣，《左傳》&quot;楚子圍許，許男面縛銜璧&quot;。</p><h3 id="井之履" tabindex="-1">井之履 <a class="header-anchor" href="#井之履" aria-label="Permalink to “井之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>百足俱行，相輔為強。三聖翼事，王室寵光。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《履》。</p><h3 id="井之泰" tabindex="-1">井之泰 <a class="header-anchor" href="#井之泰" aria-label="Permalink to “井之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>本根不固，華葉落去，更為孤嫗。通《否》。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>巽隕落，故曰本根不固。兌為華，巽落，故曰落去。巽為嫗，巽寡，故曰孤嫗。</p><h3 id="井之否" tabindex="-1">井之否 <a class="header-anchor" href="#井之否" aria-label="Permalink to “井之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>牧羊稻園，聞虎喧歡。畏懼怵惕，終無禍患。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《節》。患，各本皆作焉，依《屯》之《復》校。喧歡，宋元本作喧喧，怵惕作休息，均依汲古。</p><h3 id="井之同人" tabindex="-1">井之同人 <a class="header-anchor" href="#井之同人" aria-label="Permalink to “井之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>履位乘勢，靡有絕弊。為隸所圖，與眾庶位。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為履、為乘，坤賤，故曰隸。坤為眾庶。與眾庶位，言初得位乘勢，後為皂隸所圖，與齊民等也。</p><h3 id="井之大有" tabindex="-1">井之大有 <a class="header-anchor" href="#井之大有" aria-label="Permalink to “井之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>大輿多塵，小人傷賢。皇甫司徒，使君失家。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為大輿、為小人，艮為塵，故曰大輿多塵。艮為賢良，坤喪，故傷賢。艮為臣，故曰皇甫司徒。震為君，艮為家，震覆，坎失，故曰使君失家。《詩》：&quot;番維司徒，皇甫卿士&quot;，皆幽王臣。又&quot;無將大車，祇自塵兮；無思百憂，只自疷兮&quot;，又&quot;無將大車，維塵冥冥&quot;。</p><h3 id="井之謙" tabindex="-1">井之謙 <a class="header-anchor" href="#井之謙" aria-label="Permalink to “井之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>安如泰山，福祿屢臻。雖有狼虎，不能危身。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>○如，宋元本作和，祿作佑，依汲古。坤為安，艮為山，震東，故曰泰山。震為福祿，艮為狼虎、為身，震出，故不能危身。</p><h3 id="井之豫" tabindex="-1">井之豫 <a class="header-anchor" href="#井之豫" aria-label="Permalink to “井之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>同氣異門，各別西東。南與兇遇，北傷其孫。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>艮為氣、為門，正反皆艮，故曰同氣。兩艮相背，故曰異門。震東，坎西，故曰各別西東。震又為南，坤為兇，故與兇遇。坎又為北，坤為死，艮為孫，故曰北傷其孫。孫，與東韻。</p><h3 id="井之隨" tabindex="-1">井之隨 <a class="header-anchor" href="#井之隨" aria-label="Permalink to “井之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>蜆見不祥，禍起我鄉。行人畏懼，邑客逃藏。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>《爾雅釋蟲》：&quot;蜆，縊女也，好自經死，故見者以為不祥&quot;。互巽為蟲、為系，正縊女象也，故曰不祥。艮為我、為邑、為鄉，震為行人、為客，巽伏，故曰逃藏。○蜆，各本皆訛為霓。祇，宋元本未訛，牟庭謂黃丕烈刊宋本易林私改霓為蜆，以就爾雅，豈知巽為繩、為系，正易林用象之神妙，先儒從不知易林之詞皆由象生，故失言如此，且以好古之黃蕘圃何至改古書字乎。第四句宋元本作使命不通，依汲古。</p><h3 id="井之蠱" tabindex="-1">井之蠱 <a class="header-anchor" href="#井之蠱" aria-label="Permalink to “井之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>養虎畜狼，必見賊傷。無事招禍，自取災殃。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為虎狼，艮止為畜，巽為盜賊，兌毀折，故曰招禍、曰災殃。○宋元本作&quot;畜狼養虎，無事招禍。必見賊傷，自取災殃&quot;，今依汲古。惟必見汲古作還自，與自字義皆重，故依宋元本。</p><h3 id="井之臨" tabindex="-1">井之臨 <a class="header-anchor" href="#井之臨" aria-label="Permalink to “井之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>順風吹火，牽騎驥尾。易為功力，因權受福。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>牽騎，汲古作倖附，依宋元本。○伏遯。互巽為風，艮為火，故曰順風吹火。艮手為牽，乾為驥，艮為尾，故曰牽騎驥尾。巽為權。</p><h3 id="井之觀" tabindex="-1">井之觀 <a class="header-anchor" href="#井之觀" aria-label="Permalink to “井之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>五嶽四瀆，潤洽為德。行不失理，民賴恩福。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《明夷》。○潤洽，依校，各本作沾濡。</p><h3 id="井之噬嗑" tabindex="-1">井之噬嗑 <a class="header-anchor" href="#井之噬嗑" aria-label="Permalink to “井之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>延陵聰敏，樂聽太史。雞鳴大國，薑氏受福。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>《左傳襄二十九年》：&quot;吳季札聘魯，為之歌，齊曰：美哉，洋洋乎，大風也哉。表東海者，其太公乎&quot;。艮為山、為少，故曰延陵。札號延陵季子也。震為樂，坎耳為聽，離文，故曰太史。伏巽為雞，艮為國，巽為薑。雞鳴，《齊詩》篇名。○樂聽，汲古作聽樂，依宋元本。</p><h3 id="井之賁" tabindex="-1">井之賁 <a class="header-anchor" href="#井之賁" aria-label="Permalink to “井之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>神鳥五色，鳳凰為主。集於王國，使君得所。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為神，艮為鳥，離文，故為鳳凰。震為主、為王、為君、為國。○國，宋元本作谷，依汲古。《禮器》雲：&quot;升中於天而鳳凰降。&quot;《援神契》：&quot;鳳五色俱備，見則天下安寧&quot;。</p><h3 id="井之剝" tabindex="-1">井之剝 <a class="header-anchor" href="#井之剝" aria-label="Permalink to “井之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>媒妁無明，雖期不行。齊女長子，亂其紀網。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《井》象。坎為媒妁，坎隱伏，故無明。震為行，震反，故不行。下巽為齊女，伏震為長子。互離為亂，巽為紀網。○無，宋元本作光，行作得，其作我，均依汲古。</p><h3 id="井之復" tabindex="-1">井之復 <a class="header-anchor" href="#井之復" aria-label="Permalink to “井之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>明月作晝，大人失居。眾星宵亂，不知所據。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此仍用《井》象。兌為月，離為晝，兌離連體，故曰明月作晝。乾為大人，三陽皆陷陰中，故曰失居。離為星，坎為眾、為夜，故曰眾星宵亂。離為亂也。</p><h3 id="井之無妄" tabindex="-1">井之無妄 <a class="header-anchor" href="#井之無妄" aria-label="Permalink to “井之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>少康興起，誅澆復祖。微滅復明，享祀大禹。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為君，故曰少康、曰興起。伏坤為惡，故曰澆。坤殺，故曰誅澆，言澆為少康所誅也。艮為祖，震為復，故曰復祖。乾為大明、為王，故曰大禹。按：《帝王世紀》：&quot;后羿之相寒浞，既殺后羿，因羿之室生奡及豷，夏有力，殺夏帝相帝妃，仍氏女曰後緡逃於有仍，生少康，少康長，與夏舊臣靡誅奡，復夏室。&quot;奡即澆也。○第四句宋元本作大禹享祀，依汲古。</p><h3 id="井之大畜" tabindex="-1">井之大畜 <a class="header-anchor" href="#井之大畜" aria-label="Permalink to “井之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>千門萬戶，大福所處。黃屋左纛，龍德獨有。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>艮為門戶，乾亦為門戶、為千萬，故曰千門萬戶。乾為大福，艮為屋，震玄黃，故曰黃屋。震為旗、為左，故曰左纛。纛，旗也。震為龍、為德，龍德獨有者，言非天子不能如此也。○左，汲古訛在，有作右，均依宋元本。</p><h3 id="井之頤" tabindex="-1">井之頤 <a class="header-anchor" href="#井之頤" aria-label="Permalink to “井之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>乾作聖男，坤為智女。配合成就，長生得所。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>伏乾為聖、為男，坤為女，坎為水、為智，坤亦為水，故曰智女。乾道成男，坤道成女，故曰配合成就。震為長生。○成就，宋元本作既成，依汲古。</p><h3 id="井之大過" tabindex="-1">井之大過 <a class="header-anchor" href="#井之大過" aria-label="Permalink to “井之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>羿張烏號，彀射天狼。鐘鼓夜鳴，將軍壯心。柱國雄勇，鬬死滎陽。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。坤惡，故曰羿。艮為烏，震為鳴，故曰烏號。烏號，弓名也。艮為天、為狼，天狼，星名。《楚辭》：&quot;青雲衣兮白霓裳，舉長弓兮射天狼。&quot;彀，張弓也。彀射天狼，言羿暴戾也。震為射、為鐘鼓。坤為夜、為軍、為心、為國，艮為柱，故曰柱國。坤為死，正覆艮，故曰鬬死。坤水，故曰滎陽。柱國，房君蔡賜也，見陳涉世家，惟史不言其死處，林蓋別有所據。○彀，汲古訛殷。天，各本皆作驚，柱皆作趙，均依《師》之《否》校，然趙國或為人名，戰死滎陽，未必為訛字。</p><h3 id="井之坎" tabindex="-1">井之坎 <a class="header-anchor" href="#井之坎" aria-label="Permalink to “井之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>炙魚棝鬥，張伺夜鼠。不忍香味，機發為祟，笮不得去。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>伏巽為魚，下有離火，故曰炙魚。震為棝鬥。坎為夜、為鼠，艮止，故曰伺。震發，故曰張。言以炙魚置棝鬥之中，至夜引鼠而射殺之也。伏巽為臭，故曰香味。坎為機、為祟，震為發，艮止，故曰笮。笮，音窄，狹也、迫也。○各本祟下多祟在頭頸四字，依《歸妹》之《師》校。棝，各本多作銅，丁雲《說文》棝鬥可以射鼠，疑銅為棝之形訛字。愚按：《歸妹》之《師》作枯鬥，枯，正棝之音訛字，由此證銅確為棝，丁說是也，故竟從之。</p><h3 id="井之離" tabindex="-1">井之離 <a class="header-anchor" href="#井之離" aria-label="Permalink to “井之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>高飛不視，貪饕所在。臭腐為患，自害其身。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>離為飛、為視，巽伏，故不視。兌口為食，正反兌故曰貪饕。巽為臭腐，伏坎為患。艮為身。○其，宋元本作躬，依汲古。</p><h3 id="井之鹹" tabindex="-1">井之鹹 <a class="header-anchor" href="#井之鹹" aria-label="Permalink to “井之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>鉛刀攻玉，堅不可得。單盡我力，胝胼為疾。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《豫》。第三句依宋元本。單，殫之省文，汲古作盡我筋力。第四句宋元本作齒為疾賊，依汲古。</p><h3 id="井之恆" tabindex="-1">井之恆 <a class="header-anchor" href="#井之恆" aria-label="Permalink to “井之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>方喙宣口，聖智仁厚。解釋倒懸，家國大安。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《噬嗑》。解釋，宋元本作釋解，依汲古。家，汲古作厯，依宋元本。</p><h3 id="井之遯" tabindex="-1">井之遯 <a class="header-anchor" href="#井之遯" aria-label="Permalink to “井之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>蜘蛛南北，巡行罔罟。杜季利兵，傷我心旅。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《井》象。巽為蟲，故曰蜘蛛。離南，坎北，離為網罟。艮為少、為木，故曰杜季。艮為刀劍，故曰利兵。坎為心旅。杜季，即杜伯，《史記正義》引《周春秋》雲：宣王殺杜伯而無辜，後三年宣王會諸侯，田於圃，日中，杜伯起於道左，衣朱衣冠，操朱弓矢射宣王，中心折脊而死。《國語》則雲於鄗。○首二句各木皆作&quot;踟躕南北，誤入喪國&quot;，旅作腹，丁雲依《御覽》蜘蛛引校改，旅即膂之省文。</p><h3 id="井之大壯" tabindex="-1">井之大壯 <a class="header-anchor" href="#井之大壯" aria-label="Permalink to “井之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>公孫之政，惠而不煩。喬子相國，終身無患。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。艮為公孫，坤為政。喬，丁雲喬僑通用，鄭子產也。艮為喬木，故取象。坤為國、為終、為身、為患，艮安，故無患。</p><h3 id="井之晉" tabindex="-1">井之晉 <a class="header-anchor" href="#井之晉" aria-label="Permalink to “井之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>孤矢大張，道絕不通。小人寇賊，君子壅塞。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為弧、為矢，艮為道路，坎陷，故不通。坤為小人，艮為君子，坎為寇賊、為壅塞。</p><h3 id="井之明夷" tabindex="-1">井之明夷 <a class="header-anchor" href="#井之明夷" aria-label="Permalink to “井之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>藏戟之室，封豕受福。充澤肥腯，子孫蕃息。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坎為戟、為室、為隱伏，故曰藏。坎為豕，震為福、為大，故曰封豕。伏乾為肥腯。震為子、為蕃息。</p><h3 id="井之家人" tabindex="-1">井之家人 <a class="header-anchor" href="#井之家人" aria-label="Permalink to “井之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>八子同巢，心勞相思，雖苦無憂。伏震為子，巽數八，故曰八子。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>離為巢，坎為心、為勞、為憂。</p><h3 id="井之睽" tabindex="-1">井之睽 <a class="header-anchor" href="#井之睽" aria-label="Permalink to “井之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>循理舉手，舉求取予。六體相摩，終無殃咎。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>通《蹇》。艮為手，坤為理，二陽分居坤中，故曰循理。艮為舉求、為取予，艮為體，坎數六，故曰六體。重坎，故曰相摩。艮為終。《左傳閔元年》遇屯之比，曰六體不易。六體，即謂坎也。○舉求取予，汲古作典求相予，摩作磨，均依宋元本。殃咎，宋元本作咎殃，不協，依汲古。</p><h3 id="井之蹇" tabindex="-1">井之蹇 <a class="header-anchor" href="#井之蹇" aria-label="Permalink to “井之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>公子王孫，把彈攝丸。發輒有獲，室家饒足。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《小畜》。</p><h3 id="井之解" tabindex="-1">井之解 <a class="header-anchor" href="#井之解" aria-label="Permalink to “井之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>井渚有悔，渴霓為怪。不亟徙鄉，家受其殃。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為井、為渚、為悔，震為霓，下有離火，故曰渴霓。坎為怪，《漢書五行志》：&quot;上官桀謀廢昭帝，立燕王，是時天雨虹下屬宮中飲井水竭&quot;，《淮南子》：&quot;虹霓者，天之忌也&quot;，故不避則受其殃。○宋元本悔字均缺，依汲古。</p><h3 id="井之損" tabindex="-1">井之損 <a class="header-anchor" href="#井之損" aria-label="Permalink to “井之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>鄭會細聲，國亂失傾。弘明早見，止樂不聽。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>《左傳襄二十九年》：&quot;吳季札聘魯，觀樂，為之歌，鄭曰：美哉，其細已甚，民弗堪也，是其先亡乎？自鄶以下無譏焉&quot;，林全用其意。坤為鄭會，《左傳》作鄶，《毛詩》作檜。會，蓋其省字。震為聲，坤柔，故曰細聲。坤為國、為亂、為傾，艮為明弘。明猶弘通，住，季子也。震為樂，兌為耳、為聽，艮止，故不聽。○會細，汲古作澮有，釋文同，依宋元本。</p><h3 id="井之益" tabindex="-1">井之益 <a class="header-anchor" href="#井之益" aria-label="Permalink to “井之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>穿室鑿牆，不直生訟。褰衣涉露，雖勞無功。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>《詩召南行露篇》：&quot;厭浥行露&quot;，又雲&quot;誰謂雀無角，何以穿我屋？誰謂鼠無牙，何以穿我墉&quot;。艮為室、為墉，艮手，故曰穿鑿。正反震，故曰生訟。坤為邪，故曰不直生訟。震為衣，坤為水，故曰露。艮手震行，故曰褰衣涉露。坤為勞，坤喪，故無功。○露，汲古作河，非，依宋元本。</p><h3 id="井之夬" tabindex="-1">井之夬 <a class="header-anchor" href="#井之夬" aria-label="Permalink to “井之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>脫卵免乳，長大成就。君子萬年，動有利得。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>震為卵，今陽長至五，故曰脫卵。艮為乳，艮伏，故免乳。乾為長大、為成就、為君子、為萬年。○首句汲古作胎卵胞乳，非，依宋元本。</p><h3 id="井之姤" tabindex="-1">井之姤 <a class="header-anchor" href="#井之姤" aria-label="Permalink to “井之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>五心乖離，各引是非。莫適為主，道路塞壅。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>巽卦數五，伏坤為心、為乖離。乾為言，兌亦為言，兌背乾，故曰各引是非。《夬九四》雲&quot;聞言不信&quot;，林用象所本也。震為侯、為主、為道路，震伏，故曰莫適為主。乾實，故壅塞。</p><h3 id="井之萃" tabindex="-1">井之萃 <a class="header-anchor" href="#井之萃" aria-label="Permalink to “井之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>百柱載梁，千歲不僵。大願輔福，文武以昌。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮巽為樑柱，下坤為多，故曰百柱。坤為車，故曰載。坤為千歲、為僵，艮堅，故不僵。伏乾為大、為福，坤為文，伏震為武、為昌。</p><h3 id="井之升" tabindex="-1">井之升 <a class="header-anchor" href="#井之升" aria-label="Permalink to “井之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>營城洛邑，周公所作。世逮三十，年厯七百。福佑豐實，堅固不落。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為城邑、為世、為年，震為周、為公，數三，坤數十，故曰世逮三十。震數七，坤數百，故曰年厯七百。伏乾為福佑、為實，伏艮為堅。《左傳》周公城洛邑卜世三十，卜年七百。○逮，汲古訛連，依宋元本。</p><h3 id="井之困" tabindex="-1">井之困 <a class="header-anchor" href="#井之困" aria-label="Permalink to “井之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>從叔旅行，食於東昌。嘉伯悅喜，與我芝酒。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。艮為叔，震為從、為行旅，故曰從叔行旅。震為食、為東、為昌。東昌，齊地名。震為伯、為嘉、為喜，坎為酒，巽為芝，艮為我，故曰與我芝酒。此似有故實，俟考。</p><h3 id="井之井" tabindex="-1">井之井 <a class="header-anchor" href="#井之井" aria-label="Permalink to “井之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>營城洛邑，周公所作。世逮三十，年厯七百。福佑豐實，堅固不落。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>坤為城邑、為世、為年，震為周、為公，數三，坤數十，故曰世逮三十。震數七，坤數百，故曰年厯七百。伏乾為福佑、為實，伏艮為堅。《左傳》周公城洛邑卜世三十，卜年七百。○逮，汲古訛連，依宋元本。</p><h3 id="井之革" tabindex="-1">井之革 <a class="header-anchor" href="#井之革" aria-label="Permalink to “井之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>牛耳聾蔽，不曉聲味。委以鼎俎，方始亂潰。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。坤為牛，坎為耳，坤閉，故耳聾。巽為味，震為聲，坤閉，故不知聲味。震為鼎俎，離為亂。○潰，汲古作憒，依宋元本。牛，汲古作失，未知孰是。</p><h3 id="井之鼎" tabindex="-1">井之鼎 <a class="header-anchor" href="#井之鼎" aria-label="Permalink to “井之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>娵訾開門，鶴鳴彈冠。文章進用，舞韶和鸞。三仁翼政，國無災殃。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《明夷》。</p><h3 id="井之震" tabindex="-1">井之震 <a class="header-anchor" href="#井之震" aria-label="Permalink to “井之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>遊魂六子，百木所起。三男從父，三女隨母。至己而後，各得其所。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>震為遊、為子，坎為魂，數六，故曰遊魂六子。震為木、為百，數三。互坎艮，皆男象，而震為父、為從，故曰三男從父。伏巽，互離兌，皆女象。巽為母，故曰三女從母。離卦數三也。巽居己方，至己而反者，言震巽相反覆，震究為巽與震相反也。○反，汲古作足，非，依宋元本。</p><h3 id="井之艮" tabindex="-1">井之艮 <a class="header-anchor" href="#井之艮" aria-label="Permalink to “井之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>南山蘭茞，使君媚好。皇女長婦，多孫眾子。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>《左傳》：&quot;鄭文公有妾曰燕姞，夢天與之蘭曰：蘭有國香，人服媚之&quot;，艮納丙，故曰南山。震亦為南。震伏巽，故曰蘭茞。震為君，伏兌為媚好，伏巽為皇女、為長婦。艮為孫子，重艮，故曰多、曰眾。○首二句汲古訛為&quot;兩山萠使，苲君好&quot;，依宋元本。</p><h3 id="井之漸" tabindex="-1">井之漸 <a class="header-anchor" href="#井之漸" aria-label="Permalink to “井之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>黃虹之野，國君在位。管叔為相，國無災殃。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>巽為虹，互離，故曰黃虹。艮為野，伏震為賢君、為管，下艮，故曰管叔。管仲相齊，伯天下。《孝經援神契》曰黃虹抱曰輔臣納忠，又《帝王世紀》少昊母曰女節，見星如虹下流華渚，夢感而生少昊。○在位，汲古作所在，虹訛為●，均依宋元本。管叔，宋本、汲古作榮段，依元刊。</p><h3 id="井之歸妹" tabindex="-1">井之歸妹 <a class="header-anchor" href="#井之歸妹" aria-label="Permalink to “井之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>穿鑿道路，為君除舍。開闢福門，喜在我鄰。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>坎為穿，震為道路、為君、為喜，伏艮為門。《史記呂后紀》：&quot;東牟侯興居曰誅呂氏，無功，請得除宮&quot;。震為喜、為鄰。</p><h3 id="井之豐" tabindex="-1">井之豐 <a class="header-anchor" href="#井之豐" aria-label="Permalink to “井之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>商風數起，天下昏晦。旱魃為虐，九土兵作。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，下互巽，故曰商風。互大坎，故曰昏晦。豐卦屢言日中見鬥，林所本也。坎為鬼，下離故曰旱魃。《詩大雅》：&quot;旱魃為虐&quot;，《毛傳》：&quot;魃，旱神也&quot;。震數九，伏艮為兵。○九土，汲古作七凡，非，依宋元本。</p><h3 id="井之旅" tabindex="-1">井之旅 <a class="header-anchor" href="#井之旅" aria-label="Permalink to “井之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>自衛反魯，時不我與。冰炭異室，仁道閉塞。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《頤》。○反，宋元本作歸，閉作隔，均依汲古。</p><h3 id="井之巽" tabindex="-1">井之巽 <a class="header-anchor" href="#井之巽" aria-label="Permalink to “井之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>春陽生草，夏長條肄。萬物蕃滋，充實益有。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震為春陽、為生、為草。互離為夏，巽為枝條，震為萬物、為蕃滋。《詩周南》：&quot;伐其條肄&quot;，《傳》：&quot;斬而復生曰肄，即嫩條&quot;。○肄，各本皆作枝，非，依《巽》之《睽》校。</p><h3 id="井之兌" tabindex="-1">井之兌 <a class="header-anchor" href="#井之兌" aria-label="Permalink to “井之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>六蛇奔走，俱入茂草。驚於長註，畏懼啄口。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>互巽為蛇，伏坎，卦數六，故曰六蛇。伏震為走，巽為入、為茂草，兌為口，坎為畏，艮為黔啄。蛇最畏鸛鶴之屬，以其啄也。易林讀黔喙為黔啄，此又一證也。○俱，汲古作奔，依宋元本。註，汲古作作住，依宋本、元本。啄，各本皆作喙，依《中孚》之《家人》校。註，擊也。</p><h3 id="井之渙" tabindex="-1">井之渙 <a class="header-anchor" href="#井之渙" aria-label="Permalink to “井之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>明月照夜，使暗為晝。國有仁賢，君尊如故。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為夜、為月，故曰明月照夜。坎隱伏，艮光明，故曰使暗為晝。艮為國，震為仁、為君。○宋元本缺此林。</p><h3 id="井之節" tabindex="-1">井之節 <a class="header-anchor" href="#井之節" aria-label="Permalink to “井之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>避蛇東走，反入虎口。制於爪牙，骨為灰土。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為東，伏巽為蛇，坎隱伏，故曰避蛇東走。艮為虎，兌為口、為爪牙、為骨，坎為土。○蛇，汲古作地，為作於，依宋元本。</p><h3 id="井之中孚" tabindex="-1">井之中孚 <a class="header-anchor" href="#井之中孚" aria-label="Permalink to “井之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>傾迭不行，弱走善僵。孟縶無良，失其寵光。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為傾迭，震為走，兌折，故曰弱走善僵。震為孟，巽繩為縶，故曰孟縶。艮為良、為光，巽為伏，故曰無良、曰失其寵光。按：《左傳昭七年》：&quot;衛襄公嬖人婤姶生孟縶，孟縶之足不良，孔成子曰：孟非人也，將不列於宗，後竟不得立&quot;。孟縶無良，即謂孟縶之足不良也。</p><h3 id="井之小過" tabindex="-1">井之小過 <a class="header-anchor" href="#井之小過" aria-label="Permalink to “井之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>十羊俱見，黃頭為首。歲美民安，國樂無咎。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，數十，又為見，故曰十羊俱見。震為黃，艮為頭、為首，故曰黃頭為首。震為歲、為樂，艮為國，又為安。○羊，汲古作年，美作尾，均依宋元本。</p><h3 id="井之既濟" tabindex="-1">井之既濟 <a class="header-anchor" href="#井之既濟" aria-label="Permalink to “井之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>望風入門，來到我鄰。餔吾養均。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>互用遇卦象。○餔，汲古作鋪，依宋元本。</p><h3 id="井之未濟" tabindex="-1">井之未濟 <a class="header-anchor" href="#井之未濟" aria-label="Permalink to “井之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>登高車返，視天彌遠。虎口不張，害賊消亡。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用遇卦象。井通噬嗑。震為車、為返、為登，巽為高，故曰登高車返。艮為天、為虎，坎閉塞，故口不張。震為口也。巽為賊，風散，故消亡。○車，汲古訛連，天訛失，均依宋元本校。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
